SELECT        dbo.vwinventory_lvl1.container, dbo.vwinventory_lvl1.total_qty_on_container, dbo.vwinventory_lvl1.future_cost, dbo.vwinventory_lvl1.effective_date, dbo.vwinventory_lvl1.old_bin, 
                         ROUND(dbo.vwinventory_lvl1.forecast_usage * ISNULL(periods_to_supply.periods_to_supply, 1.3), 0) AS forecast_1_3, 
                         dbo.InlineMax(ROUND(dbo.vwinventory_lvl1.forecast_usage * ISNULL(periods_to_supply.periods_to_supply, 1.3), 0), dbo.vwinventory_lvl1.order_point) AS forecast_point, CASE WHEN replenishment_method IN ('OP/OQ', 
                         'min/max') THEN Maximum ELSE WQMetaData.dbo.inlinemax(round(forecast_usage * isnull(periods_to_supply, 1.3), 0), order_point) - net_stock END AS OQ_order_quantity, CASE WHEN replenishment_method = 'min/max' AND 
                         order_point < Net_stock AND Maximum < Net_stock THEN maximum - Net_stock WHEN replenishment_method = 'OP/OQ' AND 
                         order_point < Net_stock THEN Maximum + order_point - Net_stock WHEN replenishment_method = 'up to' THEN CAST(CASE WHEN WQMetaData.dbo.inlinemax(CAST(forecast_usage AS decimal(19, 2)) 
                         * isnull(periods_to_supply, 1.3), order_point) - net_stock < 0 THEN WQMetaData.dbo.inlinemax(CAST(forecast_usage AS decimal(19, 2)) * isnull(periods_to_supply, 1.3), order_point) - net_stock ELSE 0 END AS int) 
                         ELSE 0 END * - 1 AS excessunits, (CASE WHEN replenishment_method = 'min/max' AND order_point < Net_stock AND Maximum < Net_stock THEN maximum - Net_stock WHEN replenishment_method = 'OP/OQ' AND 
                         order_point < Net_stock THEN Maximum + order_point - Net_stock WHEN replenishment_method = 'up to' THEN CAST(CASE WHEN WQMetaData.dbo.inlinemax(CAST(forecast_usage AS decimal(19, 2)) 
                         * isnull(periods_to_supply, 1.3), order_point) - net_stock < 0 THEN WQMetaData.dbo.inlinemax(CAST(forecast_usage AS decimal(19, 2)) * isnull(periods_to_supply, 1.3), order_point) - net_stock ELSE 0 END AS int) 
                         ELSE 0 END * - 1) * (dbo.vwinventory_lvl1.Value / dbo.vwinventory_lvl1.QtyOnHand) AS excessvalue, dbo.vwinventory_lvl1.manufacturing_class_desc, dbo.vwinventory_lvl1.legacy_id, dbo.vwinventory_lvl1.legacy_company, 
                         dbo.vwinventory_lvl1.qty_backordered_inventory, dbo.vwinventory_lvl1.qty_on_sales_order, dbo.vwinventory_lvl1.qty_for_production, dbo.vwinventory_lvl1.on_sched, dbo.vwinventory_lvl1.qty_in_production, 
                         dbo.vwinventory_lvl1.qty_non_pickable, dbo.vwinventory_lvl1.qty_quarantined, dbo.vwinventory_lvl1.qty_frozen, dbo.vwinventory_lvl1.qty_on_sales_quote, dbo.vwinventory_lvl1.qty_on_special_po, 
                         dbo.vwinventory_lvl1.qty_on_ds_po, dbo.vwinventory_lvl1.qty_on_special_po_cost, dbo.vwinventory_lvl1.Net_qty_available, dbo.vwinventory_lvl1.qty_on_vessel, dbo.vwinventory_lvl1.ItemLocDelete, 
                         dbo.vwinventory_lvl1.Company, dbo.vwinventory_lvl1.Location, dbo.vwinventory_lvl1.InvenMastId, dbo.vwinventory_lvl1.PurchClass, dbo.vwinventory_lvl1.PurchDiscGroup, dbo.vwinventory_lvl1.SalesDiscGroup, 
                         dbo.vwinventory_lvl1.Stock, dbo.vwinventory_lvl1.NoCharge, dbo.vwinventory_lvl1.Requsition, dbo.vwinventory_lvl1.ReplLoc, dbo.vwinventory_lvl1.ReplMethod, dbo.vwinventory_lvl1.FirstPeriod, 
                         dbo.vwinventory_lvl1.FirstYear, dbo.vwinventory_lvl1.Bin, dbo.vwinventory_lvl1.TaxGroup, dbo.vwinventory_lvl1.DeadStock, dbo.vwinventory_lvl1.OnRelease, dbo.vwinventory_lvl1.OnBO, dbo.vwinventory_lvl1.buy, 
                         dbo.vwinventory_lvl1.make, dbo.vwinventory_lvl1.discontinued, dbo.vwinventory_lvl1.track_bins, dbo.vwinventory_lvl1.SupplierId, dbo.vwinventory_lvl1.ProdGroup, dbo.vwinventory_lvl1.DateMod, 
                         dbo.vwinventory_lvl1.DateCreated, dbo.vwinventory_lvl1.LastSale, dbo.vwinventory_lvl1.LastPurchase, dbo.vwinventory_lvl1.STCost, dbo.vwinventory_lvl1.MACost, dbo.vwinventory_lvl1.QtyOnHand, 
