                         dbo.vwinventory_lvl1.MasterPrice10, dbo.vwinventory_lvl1.sales_pricing_unit_size, dbo.vwinventory_lvl1.purchase_pricing_unit_size, dbo.vwinventory_lvl1.R12QtyShip, dbo.vwinventory_lvl1.R12Sales, 
