                         dbo.vwinventory_lvl1.R12DirectQtyShip, dbo.vwinventory_lvl1.R12DirectSales, dbo.vwinventory_lvl1.R12DirectCost, dbo.vwinventory_lvl1.R12DirectGM, dbo.vwinventory_lvl1.R12DirectLines, 
                         dbo.vwinventory_lvl1.R12WarehouseQtyShip, dbo.vwinventory_lvl1.R12WarehouseSales, dbo.vwinventory_lvl1.R12WarehouseCost, dbo.vwinventory_lvl1.R12WarehouseGM, dbo.vwinventory_lvl1.R12WarehouseLines, 
                         dbo.vwinventory_lvl1.AvgDailyCogs, dbo.vwinventory_lvl1.R12Avg_unit_price, dbo.vwinventory_lvl1.qty_ship_30, dbo.vwinventory_lvl1.qty_ship_60, dbo.vwinventory_lvl1.qty_ship_90, dbo.vwinventory_lvl1.rma_30, 
                         dbo.vwinventory_lvl1.rma_60, dbo.vwinventory_lvl1.rma_90, dbo.vwinventory_lvl1.LocationName, dbo.vwinventory_lvl1.BranchID, dbo.vwinventory_lvl1.LocationDelete, dbo.vwinventory_lvl1.branchname, 
                         dbo.vwinventory_lvl1.division_name, dbo.vwinventory_lvl1.ProdGroupDesc, dbo.vwinventory_lvl1.SupplierName, dbo.vwinventory_lvl1.company_name, dbo.vwinventory_lvl1.Default_Product_Group_Desc, 
                         dbo.vwinventory_lvl1.PurchClassDesc, dbo.vwinventory_lvl1.tax_group_description, dbo.vwinventory_lvl1.commission_class_id, dbo.vwinventory_lvl1.DefaultPurchGroup, dbo.vwinventory_lvl1.PurchGroup, 
                         dbo.vwinventory_lvl1.defaultSalesGroup, dbo.vwinventory_lvl1.SalesGroup, dbo.vwinventory_lvl1.BuyerName, dbo.vwinventory_lvl1.vendor_name, dbo.vwinventory_lvl1.vendor_id, dbo.vwinventory_lvl1.Item_Notes, 
                         dbo.vwinventory_lvl1.Value, dbo.vwinventory_lvl1.Non_special_Value, dbo.vwinventory_lvl1.Value_Mavg, dbo.vwinventory_lvl1.ValueSC, dbo.vwinventory_lvl1.Special_Qty, dbo.vwinventory_lvl1.Special_Value, 
                         dbo.vwinventory_lvl1.SpecialCost, dbo.vwinventory_lvl1.qty_to_transfer, dbo.vwinventory_lvl1.AvailToAllocate, dbo.vwinventory_lvl1.class1desc, dbo.vwinventory_lvl1.class2desc, dbo.vwinventory_lvl1.class3desc, 
