                         dbo.vwinventory_lvl1.list_price, dbo.vwinventory_lvl1.cost, dbo.vwinventory_lvl1.buyer_id, dbo.vwinventory_lvl1.average_lead_time, dbo.vwinventory_lvl1.FIFOCost, dbo.vwinventory_lvl1.FIFOQty, 
                         dbo.vwinventory_lvl1.FIFOValue, dbo.vwinventory_lvl1.Period1Usage, dbo.vwinventory_lvl1.Period2Usage, dbo.vwinventory_lvl1.Period3Usage, dbo.vwinventory_lvl1.Period4Usage, dbo.vwinventory_lvl1.Period5Usage, 
                         dbo.vwinventory_lvl1.Period6Usage, dbo.vwinventory_lvl1.Period7Usage, dbo.vwinventory_lvl1.Period8Usage, dbo.vwinventory_lvl1.Period9Usage, dbo.vwinventory_lvl1.Period10Usage, dbo.vwinventory_lvl1.Period11Usage, 
