                         dbo.vwinventory_lvl1.Period4Orders, dbo.vwinventory_lvl1.Period5Orders, dbo.vwinventory_lvl1.Period6Orders, dbo.vwinventory_lvl1.Period7Orders, dbo.vwinventory_lvl1.Period8Orders, dbo.vwinventory_lvl1.Period9Orders, 
                         dbo.vwinventory_lvl1.Period10Orders, dbo.vwinventory_lvl1.Period11Orders, dbo.vwinventory_lvl1.Period12Orders, dbo.vwinventory_lvl1.PeriodCurrentOrders, dbo.vwinventory_lvl1.sched1_usage, 
                         dbo.vwinventory_lvl1.sched2_usage, dbo.vwinventory_lvl1.sched3_usage, dbo.vwinventory_lvl1.sched4_usage, dbo.vwinventory_lvl1.sched5_usage, dbo.vwinventory_lvl1.sched6_usage, 
                         dbo.vwinventory_lvl1.Total_sched_usage_6M, dbo.vwinventory_lvl1.Total12PeriodUsage, dbo.vwinventory_lvl1.forecast_usage, dbo.vwinventory_lvl1.Periods1T6, dbo.vwinventory_lvl1.Periods7T12, 
                         dbo.vwinventory_lvl1.Total12PeriodOrders, dbo.vwinventory_lvl1.order_point, dbo.vwinventory_lvl1.alt_code, dbo.vwinventory_lvl1.orders_1, dbo.vwinventory_lvl1.orders_2, dbo.vwinventory_lvl1.orders_3, 
                         dbo.vwinventory_lvl1.orders_4, dbo.vwinventory_lvl1.orders_5, dbo.vwinventory_lvl1.orders_6, dbo.vwinventory_lvl1.orders_7, dbo.vwinventory_lvl1.orders_8, dbo.vwinventory_lvl1.orders_9, dbo.vwinventory_lvl1.orders_10, 
