                         dbo.vwinventory_lvl1.last_prod_order_date, dbo.vwinventory_lvl1.last_order_date, dbo.vwinventory_lvl1.last_purch_date, dbo.vwinventory_lvl1.first_purch_date, dbo.vwinventory_lvl1.last_xfer_to_date, 
                         dbo.vwinventory_lvl1.Max_date, dbo.vwinventory_lvl1.Months_old, dbo.vwinventory_lvl1.shipped_1, dbo.vwinventory_lvl1.shipped_2, dbo.vwinventory_lvl1.shipped_3, dbo.vwinventory_lvl1.shipped_4, 
                         dbo.vwinventory_lvl1.shipped_5, dbo.vwinventory_lvl1.shipped_6, dbo.vwinventory_lvl1.shipped_7, dbo.vwinventory_lvl1.shipped_8, dbo.vwinventory_lvl1.shipped_9, dbo.vwinventory_lvl1.shipped_10, 
                         dbo.vwinventory_lvl1.shipped_11, dbo.vwinventory_lvl1.shipped_12, dbo.vwinventory_lvl1.shipped_mtd, dbo.vwinventory_lvl1.total_shipped_last_12_mtd, dbo.vwinventory_lvl1.created_by, 
                         dbo.vwinventory_lvl1.qty_shipped_30d, dbo.vwinventory_lvl1.qty_shipped_60d, dbo.vwinventory_lvl1.qty_shipped_90d, dbo.vwinventory_lvl1.safety_stock_days, dbo.vwinventory_lvl1.lead_time_days, 
                         dbo.vwinventory_lvl1.blanket_PO_qty, dbo.vwinventory_lvl1.Net_stock, dbo.vwinventory_lvl1.demand_pattern, dbo.vwinventory_lvl1.safety_stock_type, dbo.vwinventory_lvl1.demand_pattern_behavior, 
                         dbo.vwinventory_lvl1.periods_to_supply_max, dbo.vwinventory_lvl1.periods_to_supply_min, dbo.vwinventory_lvl1.replenishment_method, dbo.vwinventory_lvl1.last_rec_po, dbo.vwinventory_lvl1.last_rec_po_with_disc, 
                         periods_to_supply.inv_mast_uid, periods_to_supply.location_id, periods_to_supply.periods_to_supply, dbo.vwinventory_lvl1.supplier_sort_code, dbo.vwinventory_lvl1.legacy_item_id, 
                         dbo.vwinventory_lvl1.legacy_item_description
FROM            dbo.vwinventory_lvl1 LEFT OUTER JOIN
                             (SELECT        inv_loc.inv_mast_uid, inv_loc.location_id, CASE WHEN COALESCE (inv_period_usage.forecast_usage, 0.000000000) 
                                                         * company.number_of_demand_periods / item_uom.unit_size > COALESCE (NULLIF (location.high_velocity_level, 0), CAST(ss_high.value AS decimal(9))) THEN COALESCE (high_level_months, 0.000000000) 
                                                         WHEN COALESCE (inv_period_usage.forecast_usage, 0.000000000) * company.number_of_demand_periods / item_uom.unit_size > COALESCE (NULLIF (location.mid_velocity_level, 0), 
                                                         CAST(ss_mid.value AS decimal(9))) THEN COALESCE (mid_level_months, 0.000000000) ELSE COALESCE (low_level_months, 0.000000000) END AS periods_to_supply
                               FROM            P21.dbo.inv_loc AS inv_loc INNER JOIN
                                                         P21.dbo.company AS company ON company.company_id = inv_loc.company_id INNER JOIN
                                                         P21.dbo.inv_mast AS inv_mast ON inv_loc.inv_mast_uid = inv_mast.inv_mast_uid AND inv_mast.delete_flag = 'N' INNER JOIN
                                                         P21.dbo.location AS location ON location.location_id = inv_loc.location_id INNER JOIN
                                                         P21.dbo.item_uom AS item_uom ON item_uom.inv_mast_uid = inv_mast.inv_mast_uid AND item_uom.unit_of_measure = inv_mast.default_selling_unit LEFT OUTER JOIN
                                                         P21.dbo.purchase_class AS purchase_class ON purchase_class.purchase_class_id = inv_loc.purchase_class LEFT OUTER JOIN
                                                         P21.dbo.demand_period AS demand_period ON demand_period.company_id = inv_loc.company_id AND GETDATE() BETWEEN demand_period.beginning_date AND demand_period.ending_date LEFT OUTER JOIN
                                                         P21.dbo.inv_period_usage AS inv_period_usage WITH (NOLOCK) ON inv_period_usage.demand_period_uid = demand_period.demand_period_uid AND 
                                                         inv_period_usage.inv_mast_uid = inv_loc.inv_mast_uid AND inv_period_usage.location_id = inv_loc.location_id CROSS JOIN
                                                         P21.dbo.system_setting AS ss_cost_basis CROSS JOIN
                                                         P21.dbo.system_setting AS ss_high CROSS JOIN
                                                         P21.dbo.system_setting AS ss_mid CROSS JOIN
                                                         P21.dbo.system_setting AS eoqlimit
                               WHERE        (eoqlimit.name = 'useeoqlimitsontransfers') AND (ss_high.configuration_id = 0) AND (ss_high.name = 'high_velocity_level') AND (ss_mid.configuration_id = 0) AND (ss_mid.name = 'mid_velocity_level') AND 
                                                         (ss_cost_basis.configuration_id = 0) AND (ss_cost_basis.name = 'inventory_costing_basis') AND (inv_loc.replenishment_method IN ('UP TO', 'EOQ'))) AS periods_to_supply ON 
                         periods_to_supply.inv_mast_uid = dbo.vwinventory_lvl1.InvenMastId AND periods_to_supply.location_id = dbo.vwinventory_lvl1.Location